// Authoritative provider->icon mapping used whenever we have a real
// `brand` string from an API (Pollinations' /*/models catalogs return
// this directly — no guessing needed). Keyed lowercase.
const BRAND_TO_ICON_KEY = {
  openai: "openai",
  anthropic: "anthropic",
  google: "google",
  meta: "meta",
  mistral: "mistral",
  "mistral ai": "mistral",
  deepseek: "deepseek",
  alibaba: "qwen",
  qwen: "qwen",
  xai: "xai",
  cohere: "cohere",
  microsoft: "microsoft",
  amazon: "amazon",
  nvidia: "nvidia",
  ollama: "ollama",
  "hugging face": "huggingface",
  huggingface: "huggingface",
  "stability ai": "stability",
  stability: "stability",
  perplexity: "perplexity",
  elevenlabs: "elevenlabs",
};

// Ordered list of [regex, providerKey] — first match wins. Order matters:
// more specific families before broad catch-alls.
const MODEL_PROVIDER_RULES = [
  [/claude/i, "anthropic"],
  [/gemini|gemma|palm|bison/i, "google"],
  [/gpt|^o[1-9](-|$)|chatgpt|davinci|dall-?e|whisper|^tts-|text-embedding|omni-moderation/i, "openai"],
  [/llama|meta-llama/i, "meta"],
  [/mistral|mixtral|codestral|pixtral|magistral/i, "mistral"],
  [/deepseek/i, "deepseek"],
  [/qwen|qwq/i, "qwen"],
  [/grok/i, "xai"],
  [/sonar|perplexity/i, "perplexity"],
  [/nova-|titan/i, "amazon"],
  [/phi-?\d|phi3|phi4/i, "microsoft"],
  [/nemotron/i, "nvidia"],
  [/command|aya-/i, "cohere"],
  [/stable-diffusion|^sd-|sdxl|stability/i, "stability"],
  [/huggingface|hf-/i, "huggingface"],
  [/ollama/i, "ollama"],
];

function detectProviderKey(modelId) {
  if (!modelId) return "generic";
  for (const [re, key] of MODEL_PROVIDER_RULES) {
    if (re.test(modelId)) return key;
  }
  return "generic";
}

// `modelOrId` is either a plain model id string (heuristic detection only)
// or a richer {id, brand} object — pass the object whenever you have one
// (from a fetched model catalog entry) for accurate, non-guessed icons.
function providerIconHtml(modelOrId, size) {
  let key;
  if (modelOrId && typeof modelOrId === "object") {
    const brandKey = modelOrId.brand && BRAND_TO_ICON_KEY[modelOrId.brand.toLowerCase()];
    key = brandKey || detectProviderKey(modelOrId.id);
  } else {
    key = detectProviderKey(modelOrId);
  }
  const icon = PROVIDER_ICONS[key] || PROVIDER_ICONS.generic;
  const px = size || 16;
  const stroke = icon.stroke
    ? `fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"`
    : `fill="currentColor"`;
  return `<svg class="model-icon" viewBox="${icon.viewBox}" width="${px}" height="${px}" style="color:${icon.color}" aria-label="${icon.label}"><path ${stroke} d="${icon.path}"/></svg>`;
}

// Capability heuristics — used to sort fetched models into the right
// picker (chat/vision/image/video/tts/stt) since list endpoints rarely
// advertise this explicitly.
function detectCapabilities(modelId) {
  const s = (modelId || "").toLowerCase();
  const cap = { chat: false, vision: false, image: false, video: false, tts: false, stt: false };

  if (/whisper|transcribe|^stt-|speech-to-text/.test(s)) {
    cap.stt = true;
  } else if (/tts|^tts-|text-to-speech|-audio$|^audio-|openai-audio/.test(s) && !/audio-preview/.test(s)) {
    cap.tts = true;
  } else if (/sora|veo|runway|kling|luma|pika|video/.test(s)) {
    cap.video = true;
  } else if (/dall-?e|flux|dreamshaper|stable-diffusion|^sd-|sdxl|kontext|midjourney|imagen|playground-v|turbo-image|nova-canvas|image-gen|gpt-image/.test(s)) {
    cap.image = true;
  } else {
    cap.chat = true;
  }

  if (/vision|gpt-4o|gpt-4-turbo|gpt-4\.1|gpt-5|claude-3|claude-4|claude-opus|claude-sonnet|gemini|llava|pixtral|qwen-vl|internvl|kontext/.test(s)) {
    cap.vision = true;
  }
  return cap;
}

// A tiny curated fallback used when a provider's /models endpoint can't be
// reached at all, so the app is still usable out of the box.
const FALLBACK_MODELS = {
  pollinations: [
    { id: "openai", owned_by: "pollinations" },
    { id: "openai-large", owned_by: "pollinations" },
    { id: "claude", owned_by: "pollinations" },
    { id: "mistral", owned_by: "pollinations" },
    { id: "flux", owned_by: "pollinations" },
    { id: "turbo", owned_by: "pollinations" },
    { id: "kontext", owned_by: "pollinations" },
    { id: "openai-audio", owned_by: "pollinations" },
  ],
  custom: [
    { id: "gpt-4o-mini", owned_by: "" },
    { id: "gpt-4o", owned_by: "" },
  ],
};
